const input = $input.first().json;
const event = input.body;
const eventData = event.data?.object || {};

// Validation event
if (!event || !event.type || !event.id) {
  return [{ json: { success: false, error: { code: 400, message: 'Event invalide' } } }];
}

const handledTypes = ['checkout.session.completed', 'invoice.paid', 'customer.subscription.deleted'];

if (!handledTypes.includes(event.type)) {
  return [{ json: { success: false, error: { code: 200, message: `Event ${event.type} ignoré` } } }];
}

// Extraire métadonnées selon le type
let metadata = {};

if (event.type === 'invoice.paid') {
  metadata = eventData.lines?.data?.[0]?.metadata || eventData.parent?.subscription_details?.metadata || {};
} else {
  metadata = eventData.metadata || {};
}

const projectId = metadata.project_id;
const discordUserId = metadata.discord_user_id;
const backendApiUrl = metadata.backend_api_url;
const backendServiceToken = metadata.backend_service_token;

// Validations
if (!projectId || !discordUserId) {
  return [{ json: { success: false, error: { code: 400, message: 'Metadata manquantes: project_id ou discord_user_id' } } }];
}

if (!backendApiUrl || !backendServiceToken) {
  return [{ json: { success: false, error: { code: 400, message: 'Backend credentials manquantes dans metadata (bot Discord doit les ajouter)' } } }];
}

// Extraire IDs Stripe
let stripeSessionId = null;
let stripeInvoiceId = null;
let stripeCustomerId = eventData.customer || null;
let stripeSubscriptionId =
  eventData.subscription ||
  eventData.parent?.subscription_details?.subscription ||
  eventData.lines?.data?.[0]?.parent?.subscription_item_details?.subscription ||
  null;

let periodEnd = null;
const customerEmail = eventData.customer_details?.email || eventData.customer_email || null;

if (event.type === 'checkout.session.completed') {
  stripeSessionId = eventData.id;
} else if (event.type === 'invoice.paid') {
  stripeInvoiceId = eventData.id;
  periodEnd = eventData.lines?.data?.[0]?.period?.end || null;
}

return [{
  json: {
    success: true,
    project_id: projectId,
    discord_user_id: discordUserId,
    backend_api_url: backendApiUrl,
    backend_service_token: backendServiceToken,
    discord_channel_id: metadata.discord_channel_id || null,
    discord_guild_id: metadata.discord_guild_id || null,
    discord_username: metadata.discord_username || null,
    customer_email: customerEmail,
    plan_id: metadata.plan_id || null,
    credits_per_month: metadata.credits_per_month || "1000",
    event_id: event.id,
    event_type: event.type,
    stripe_session_id: stripeSessionId,
    stripe_invoice_id: stripeInvoiceId,
    stripe_customer_id: stripeCustomerId,
    stripe_subscription_id: stripeSubscriptionId,
    period_end: periodEnd,
    hosted_invoice_url: eventData.hosted_invoice_url || null,
    invoice_pdf: eventData.invoice_pdf || null
  }
}];

const extractData = $('Extract & Validate').first().json;
const eventType = extractData.event_type;

let action = null;
let subscriptionStatus = null;
let currentPeriodEnd = null;

let payload = {
  project_id: extractData.project_id,
  project_slug: extractData.project_id,
  discord_user_id: extractData.discord_user_id,
  discord_channel_id: extractData.discord_channel_id,
  discord_guild_id: extractData.discord_guild_id,
  discord_username: extractData.discord_username,
  customer_email: extractData.customer_email,
  plan_id: extractData.plan_id,
  hostedInvoiceUrl: extractData.hosted_invoice_url || null,
  invoicePdf: extractData.invoice_pdf || null,
};

// Construire metadata Stripe
const metadata = {
  stripe_session_id: extractData.stripe_session_id || null,
  stripe_customer_id: extractData.stripe_customer_id || null,
  stripe_subscription_id: extractData.stripe_subscription_id || null,
  stripe_invoice_id: extractData.stripe_invoice_id || null
};

if (eventType === 'checkout.session.completed') {
  return [{ json: { action: 'skip', reason: 'credits driven by invoice.paid' } }];
  /*
  const credits = parseInt(extractData.credits_per_month || '1000');
  action = 'upsert';
  payload.credits_remaining = credits;
  payload.credits_total = credits;
  payload.reason = 'checkout_completed';

  // Nouveau: statut et période
  subscriptionStatus = 'active';
  const now = new Date();
  now.setMonth(now.getMonth() + 1);
  currentPeriodEnd = now.toISOString();
 */
}
else if (eventType === 'invoice.paid') {
  const credits = parseInt(extractData.credits_per_month || '1000');
  action = 'upsert';
  payload.credits_remaining = credits;
  payload.credits_total = credits;
  payload.reason = 'renewal';

  // Nouveau: statut et période
  subscriptionStatus = 'active';
  if (extractData.period_end) {
    currentPeriodEnd = new Date(extractData.period_end * 1000).toISOString();
  } else {
    const now = new Date();
    now.setMonth(now.getMonth() + 1);
    currentPeriodEnd = now.toISOString();
  }
}
else if (eventType === 'customer.subscription.deleted') {
  action = 'upsert';
  payload.credits_remaining = 0;
  payload.credits_total = 0;
  payload.reason = 'subscription_deleted';

  // Nouveau: statut canceled
  subscriptionStatus = 'canceled';
  currentPeriodEnd = new Date().toISOString();
}
else {
  return [{ json: { action: 'skip', reason: `Event ${eventType} not handled` } }];
}

return [{
  json: {
    action,
    ...payload,
    subscription_status: subscriptionStatus,
    current_period_end: currentPeriodEnd,
    metadata: metadata
  }
}];

const apiResponse = $input.first().json;
const config = apiResponse.body || apiResponse;

return [{
  json: {
    ...$('Process Event').first().json,
    stripe_key: config.stripe_key,
    backend_api_url: config.backend_api_url,
    backend_service_token: config.backend_service_token
  }
}];

// Extract backend credentials from API response
//const apiResponse = $input.first().json;
const extractData = $('Extract & Validate').first().json;

return [{
  json: {
    ...extractData,    
  }
}];

